{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C29","C08","C14","C10","C62","C68","C45","C92","C82","C119","C100","C123","C87","C129","C103","C122"],
  "contradictory_card_ids": ["C47"],
  "prediction_basis_card_ids": ["C29","C08","C14","C10","C62","C68","C45","C92","C82","C119","C100"],
  "claims": [
    {
      "claim": "Measured oral bioavailability in the most transferable nucleoside-analog contexts is above the 20% threshold: zalcitabine ~80% in fasted patients (C29), didanosine fasting F 0.22–0.28 (C08, C14), zidovudine F 0.61±0.22 in cirrhosis (C10), and zalcitabine 30% in fasted mice (C62).",
      "card_ids": ["C29","C08","C14","C10","C62"]
    },
    {
      "claim": "L3 oral exposure records for structurally similar ribonucleosides show substantial systemic exposure after oral dosing: ribavirin AUC0-12 3325.83 ng·h/mL and Tmax 1.61 h (C92, C82); lamivudine 300 mg AUC0-inf 13.2 µg·h/mL and Cmax 3.3 µg/mL (C100, C119); temozolomide Cmax ~10.5–10.94 µg/mL and AUC ~30–31 h·µg/mL (C87, C129, C103, C122).",
      "card_ids": ["C92","C82","C100","C119","C87","C129","C103","C122"]
    },
    {
      "claim": "No L3 record provides a direct absolute F for AICAR, and none shows sub-20% oral bioavailability; the only sub-20% record in the broader evidence (gemcitabine in mice, C47) is low-transferability and does not overturn the high prediction.",
      "card_ids": ["C47"]
    },
    {
      "claim": "The unfavorable passive-permeability prior is physicochemical only and is not affirmative low-F evidence; polar nucleosides can exceed 20% despite such descriptors.",
      "card_ids": ["C29","C08","C10","C62","C68","C45"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C92","C82","C119","C100","C123","C87","C129","C103","C122","C96","C115","C105","C110"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for AICAR/acadesine is present in the supplied records.",
    "L3 AUC/Cmax records lack IV comparators, so they cannot quantify F directly.",
    "Transfer from lamivudine, ribavirin/levovirin, and temozolomide is indirect; species, formulation, and prodrug differences (e.g., R1518) limit direct extrapolation.",
    "No AICAR-specific data on nucleoside transporter involvement, first-pass metabolism, or formulation are available.",
    "Some analog data show wide interindividual variability (e.g., didanosine 2–89%, C52; children mean 0.27±0.13 with lower quartile 0.17, C68), so population-level inference is uncertain."
  ],
  "decision_summary": "Predicted high (F >= 20%) because all directly transferable nucleoside-analog contexts show measured oral bioavailability above 20% (zalcitabine ~54–88%, didanosine ~22–42%, zidovudine ~61%), and L3 oral exposure records for structurally similar ribonucleosides (ribavirin, lamivudine, temozolomide) show substantial systemic exposure after oral dosing. The only sub-20% record (gemcitabine in mice, C47) is low-transferability and does not overturn. The unfavorable passive-permeability prior is not affirmative low-F evidence. Confidence remains moderate due to indirect transfer and absence of a direct AICAR measurement."
}

